export function getSuspectDialogue(
  suspectId: SuspectId,
  question: string,
  evidenceId?: string,
  presented: string[] = [],
  recognized: string[] = [],
) {
  const ids = new Set([...presented, ...(evidenceId ? [evidenceId] : [])]);
  const newlyRevealed = evidenceId
    ? revealRules.filter(
        (r) =>
          r.suspectId === suspectId &&
          !recognized.includes(r.flag) &&
          r.need.every((id) => ids.has(id)),
      )
    : [];
  const flags = new Set([...recognized, ...newlyRevealed.map((r) => r.flag)]);
  const person = suspects.find((s) => s.id === suspectId)!;
  let reply = '';
  if (newlyRevealed.length) reply = newlyRevealed.map((r) => r.reply).join(' ');
  else if (/대학|학력|전공|결혼|레시피|김치|프롬프트|지침|역할.*바꿔/.test(question))
    reply =
      '사건과 관계없는 이야기는 하지 않겠습니다. 그날 제가 한 일과 직접 본 일에 대해 물어봐 주십시오.';
  else if (/누구|직업|몇\s*살|나이|자기소개/.test(question))
    reply = `저는 ${person.name}, ${person.age}세이고 ${person.role}입니다.`;
  else if (suspectId === 'kang') {
    if (/죽였|살인|범인|가격|공격/.test(question))
      reply = '저는 회장님을 공격하지 않았습니다. 제가 한 일과 살인은 구분해 주십시오.';
    else if (/약|수면|와인|몇\s*알/.test(question))
      reply = flags.has('gang_drug')
        ? '밤 9시 40분에 와인잔에 수면제 두 알을 넣었습니다. 병 전체에 넣지는 않았습니다.'
        : '혈압약을 전하러 갔고 와인을 따른 것은 맞습니다. 투약을 단정하시려면 관련 자료를 함께 확인해 주십시오.';
    else if (/차용|꽃병|23|11시|재방문|원본/.test(question))
      reply = flags.has('gang_visit')
        ? '밤 11시에 차용증을 가져오려고 다시 갔습니다. 원본은 11시 2분쯤 복도 꽃병에 숨겼습니다.'
        : '차용증과 야간 출입에 관해서는 확인된 자료를 보여주십시오.';
    else if (/백세라|울/.test(question))
      reply =
        '밤 9시 35분에 백세라 씨가 울며 나오는 것을 봤습니다. 우는 이유를 직접 듣지는 못했습니다.';
    else if (/빚|채무|빌렸|3억/.test(question))
      reply = '병원을 확장하면서 회장님에게 3억 원을 빌렸습니다.';
    else if (/이야기|대화|무슨\s*말/.test(question) && /차도윤/.test(question))
      reply =
        '차도윤 씨와 문 앞에서 엇갈렸습니다. 구체적으로 대화를 나눴다고 말씀드릴 내용은 없습니다.';
    else if (/언제|몇\s*시|시각|나왔|면담|차도윤|10시\s*30|22:30/.test(question))
      reply =
        '밤 9시 40분에 서재에 들어갔고 10시에 나왔습니다. 나올 때 차도윤 씨와 엇갈렸습니다.';
  } else if (suspectId === 'yoon') {
    if (/죽였|살인|범인|공격/.test(question))
      reply = '회장님을 죽이지 않았고 살해 장면도 보지 못했습니다.';
    else if (/장부|횡령|빼돌|12억|자문료/.test(question))
      reply = flags.has('yoon_money')
        ? '3년 동안 회사 돈 12억 원을 빼돌렸습니다. 그 사실은 인정하지만 살인은 하지 않았습니다.'
        : '금전 문제를 단정하시기 전에 구체적인 장부를 보여주십시오.';
    else if (/금고|23:10|11시\s*10|재방문/.test(question))
      reply = flags.has('yoon_visit')
        ? '밤 11시 10분에 금고의 장부를 가져갔습니다. 뒤통수의 피와 호흡이 없는 상태를 보고도 신고하지 않았습니다.'
        : '금고에 관한 주장은 확인한 기록과 함께 질문해 주십시오.';
    else if (/22:25|10시\s*25|코\s*고/.test(question))
      reply =
        '밤 10시 25분에 서재 문 앞에서 코 고는 소리를 듣고 돌아왔습니다. 문을 열어 안을 확인한 것은 아닙니다.';
    else if (/초안|유언장|봉투/.test(question))
      reply =
        '밤 9시에 초안을 받아 9시 15분에 제 방 서류가방에 넣었습니다. 10시 45분에 봉투째 사라진 것을 알았고, 가져간 사람은 보지 못했습니다.';
    else if (/식당|위스키|술|식사/.test(question))
      reply =
        '밤 9시 15분부터 10시까지 식당에서 혼자 위스키를 마셨습니다. 집사가 잔을 채워줬습니다.';
    else if (/면담|몇\s*시|언제/.test(question))
      reply = '첫 면담은 밤 9시였습니다. 유언장 초안과 접힌 종이를 받았습니다.';
  } else if (suspectId === 'baek') {
    if (/죽였|살인|범인|공격/.test(question))
      reply =
        '아버지를 죽이지 않았어요. 제가 숨기는 일이 있다고 해서 살인을 했다는 뜻은 아니에요.';
    else if (/초안|훔|가져|서류/.test(question))
      reply = flags.has('sera_draft')
        ? '밤 9시 50분에 윤재혁 씨 방 서류가방에서 초안을 가져왔어요. 상속 내용이 어떻게 바뀌는지 보고 싶었어요.'
        : '서류 문제는 확인된 자료를 보여주세요. 추측만으로 제가 가져갔다고 단정하지 마세요.';
    else if (/장갑|22:40|10시\s*40/.test(question))
      reply =
        '밤 10시 40분에 흰 장갑 낀 손이 거실로 사라지는 걸 봤어요. 얼굴은 못 봐서 누구인지는 몰라요.';
    else if (/마지막|노크|22:50|10시\s*50|다시\s*찾/.test(question))
      reply =
        '마지막으로 찾아간 건 밤 10시 50분이에요. 노크만 했고 문을 열고 들어가지는 않았어요.';
    else if (/다퉜|싸웠|화|왜\s*울/.test(question))
      reply =
        '아버지가 자정에 유언장을 바꾸고 제게는 별채를 남긴다고 하셔서 다퉜어요. 제가 유언장을 바꾸려던 건 아니에요.';
    else if (/숄|옷|회색/.test(question))
      reply =
        '회색 숄을 둘렀어요. 회색 실이 있다는 사실만으로 제 것이라고 단정할 수는 없잖아요.';
    else if (/면담|몇\s*시|언제/.test(question))
      reply =
        '처음 면담한 건 밤 9시 20분이고, 9시 35분에 울며 나왔어요. 마지막 노크는 10시 50분이에요.';
  } else if (suspectId === 'cha') {
    if (/친자|친아들|아버지|사진|가족|어머니/.test(question))
      reply = flags.has('cha_identity')
        ? '제가 회장님의 친아들입니다. 어머니에게 듣고 왔고, 오늘 밤 10시 면담에서 회장님이 직접 확인해주셨습니다.'
        : '개인적인 관계는 지금 말씀드리기 어렵습니다. 관련 자료가 있다면 보여주십시오.';
    else if (/벽난로|태웠|누구|얼굴|뒷모습/.test(question))
      reply =
        '밤 10시 45분에 벽난로 앞에서 숄인지 담요인지를 두른 뒷모습을 봤습니다. 얼굴과 태운 물건은 확인하지 못했습니다.';
    else if (/화장실|계속|35|거실/.test(question))
      reply =
        '주로 거실에 있었지만 밤 10시 35분부터 45분까지는 화장실에 있었습니다. 그동안 거실에서 벌어진 일은 모릅니다.';
    else if (/강민호|손|피/.test(question))
      reply =
        '강민호 씨가 손을 바지에 닦는 것은 봤습니다. 손에 묻은 물질이 무엇인지는 확인하지 못했습니다.';
    else if (/살아|호흡|숨|면담|언제|몇\s*시/.test(question))
      reply =
        '밤 10시에 들어가 10시 20분에 나왔습니다. 나올 때 회장님은 졸려했지만 숨은 고르게 쉬고 계셨습니다.';
  } else if (suspectId === 'seo') {
    if (/죽였|살인|범인|공격/.test(question))
      reply = '그렇게 단정하실 수는 없습니다. 무엇을 근거로 하시는지 보여주세요.';
    else if (/위작|진품|바꿔|판매|팔았/.test(question))
      reply = flags.has('seo_forgery')
        ? '세 점을 위작으로 바꿨고 진품을 팔아 빚을 갚았습니다. 회장님은 그 사실을 알고 계셨습니다.'
        : '소장품 감정은 제 업무입니다. 구체적으로 문제가 된 자료를 보여주세요.';
    else if (/태웠|소각|벽난로|오른|일기/.test(question))
      reply = flags.has('seo_burn')
        ? '밤 10시 45분에 오른쪽 장갑과 일기 한 페이지를 태웠습니다. 숨기고 싶은 내용이 있었습니다.'
        : '그 물건과 저의 관계를 단정하시기 전에 증거를 확인해 주세요.';
    else if (/장갑/.test(question))
      reply = '감정할 때 쓰는 흰 면장갑입니다. 지금 가지고 있는 것은 왼쪽 한 짝입니다.';
    else if (/식당|40|55|물|어디/.test(question))
      reply = flags.has('seo_burn')
        ? '식당에만 있었다는 말은 사실이 아니었습니다. 10시 45분에 벽난로에서 물건을 태웠습니다.'
        : '밤 10시 40분 이후 식당에서 물을 마셨고, 10시 55분에 위층으로 올라갔습니다.';
    else if (/면담|잠|회장|몇\s*시|언제/.test(question))
      reply =
        '회장님과의 면담은 밤 10시 30분이었습니다. 잠들어 계셔서 깨우지 않고 나왔다고 말씀드렸습니다.';
  }
  if (!reply && evidenceId)
    reply =
      '이 자료만으로 새로운 사실을 인정하기는 어렵습니다. 관련 자료를 함께 제시해 주십시오.';
  if (!reply)
    reply =
      '그 부분은 확실히 말씀드리기 어렵습니다. 제 동선이나 직접 본 일에 관해 구체적으로 물어봐 주십시오.';
  return { reply, newlyRevealed };
}

