export function resolveTopic(speaker: SuspectId, question: string, explicit?: string) {
  if (explicit)
    return getInterviewTopics(speaker).some((t) => t.id === explicit) ? explicit : null;
  const other = suspects.find(
    (p) =>
      p.id !== speaker &&
      question.includes(p.name) &&
      /대해|알고|보았|봤|관계/.test(question),
  );
  if (other) return 'about-' + other.id;
  if (/동선|행적|그날 밤.*행동/.test(question)) return 'movement';
  return undefined;
}

