export function topicAnswer(speaker: SuspectId, topic: string, flags: string[]) {
  if (topic === 'movement') {
    const entries = movements(speaker, flags);
    return { reply: entries.map((e) => e.text).join('\n'), entries };
  }
  const target = topic.slice(6) as SuspectId;
  const relationship = relationships[speaker][target];
  if (!relationship) return null;
  const name = suspects.find((p) => p.id === target)!.name;
  const entry: Entry = {
    key: 'about-' + target,
    title: name + '에 대한 진술',
    text: relationship[1],
    nature: relationship[0],
    target,
  };
  if (speaker === 'kang' && target === 'baek')
    Object.assign(entry, { time: '21:35', start: 1295 });
  if (speaker === 'cha' && target === 'kang')
    Object.assign(entry, { time: '22:00', start: 1320 });
  if (speaker === 'seo' && target === 'baek')
    Object.assign(entry, { time: '21:50', start: 1310 });
  return { reply: entry.text, entries: [entry] };
}

