export function recordStatements(
  state: GameState,
  speaker: SuspectId,
  topic: string,
  entries: Entry[],
  refs: AcquiredStatement['sourceRefs'],
) {
  for (const entry of entries) {
    // Keep the first acquired version. Changed claims get a separate stable ID.
    const id = speaker + '-' + entry.key;
    if (Object.hasOwn(state.statements, id)) continue;
    const section = topic.startsWith('about-')
      ? '다른 사람들에 대해'
      : '그날 밤 당신의 행동';
    const name = suspects.find((p) => p.id === speaker)!.name;
    state.statements[id] = {
      id,
      code: 'ST-' + String(Object.keys(state.statements).length + 1).padStart(3, '0'),
      speaker,
      topic,
      title: entry.title,
      excerpt: entry.text,
      nature: entry.nature,
      target: entry.target,
      time: entry.time,
      start: entry.start,
      end: entry.end,
      supersedes: entry.supersedes,
      sourceRefs: refs,
      messageIndex: state.messages.length - 1,
      source: {
        file: '01_대본_' + name + '.pdf',
        pages: characterScripts[speaker].sections[section].pages,
        section,
      },
    };
  }
}

export function recordAdmissions(
  state: GameState,
  speaker: SuspectId,
  flags: string[],
  refs: AcquiredStatement['sourceRefs'],
) {
  recordStatements(
    state,
    speaker,
    'admission',
    flags.map((flag) => admissions[flag]).filter(Boolean),
    refs,
  );
}

export function admissionReply(flags: string[]) {
  return flags
    .map(
      (flag) =>
        admissions[flag]?.text ??
        (
          {
            weapon_fit:
              '부엉이상 받침과 검시 손상이 부합한다는 지적은 알겠습니다. 누가 사용했는지는 이 자료만으로 단정할 수 없습니다.',
            witness_gap:
              '22시 35분부터 45분까지 화장실에 있었습니다. 뒷모습뿐이라 신원과 태운 물건을 확인하지 못했습니다.',
          } as Record<string, string>
        )[flag],
    )
    .filter(Boolean)
    .join('\n');
}

