export function recordLegacyReply(
  state: GameState,
  speaker: SuspectId,
  reply: string,
  refs: AcquiredStatement['sourceRefs'],
) {
  const signatures: Record<string, string> = {
    'baek-white-glove': '얼굴은 못 봐',
    'baek-knock': '노크만 했고',
    'cha-fireplace': '얼굴과 태운 물건은 확인하지',
    'cha-breathing': '숨은 고르게',
    'cha-absence': '그동안 거실에서',
    'yoon-snoring': '코 고는 소리를 듣고',
    'yoon-missing-draft': '봉투째 사라진',
    'kang-crying': '울며 나오는',
    'seo-dining-claim': '식당에서 물을 마셨고',
  };
  const entries = movements(speaker, state.revealed)
    .filter(
      (entry) =>
        signatures[speaker + '-' + entry.key] &&
        reply.includes(signatures[speaker + '-' + entry.key]),
    )
    .map((entry) => ({ ...entry, text: reply }));
  recordStatements(state, speaker, 'movement', entries, refs);
}
